// builds edits_D.json from the new line sets below; old lines are parsed from packet_D.md
// marks are written short ("~1 ^мені|любимчик>заслужив"); the scene prefix is added to every thread token.
const fs = require('fs'), path = require('path');
const dir = __dirname;
const pk = fs.readFileSync(path.join(dir, 'packet_D.md'), 'utf8').split(/\r?\n/);
const old = {}; let cur = null;
for (const l of pk) {
  const h = /^### ([HM]) @(\S+)/.exec(l); if (h) { cur = h[1] + ':' + h[2]; old[cur] = []; continue; }
  if (cur && /^\d+ \| /.test(l)) { const parts = l.split(' | '); old[cur].push(parts[1].trim()); }
  else if (l.startsWith('#')) cur = null;
}
const pre = (sc, mk) => mk.replace(/\^(\S+)/, (m, t) => '^' + t.split('>').map(side => side.split('|').map(x => sc + '.' + x).join('|')).join('>'));

