// ---------- build ----------
const out = [];
for (const key of Object.keys(N)) {
  const [who, list] = key.split(':'); const o = old[key]; if (!o) throw new Error('no old list ' + key);
  N[key].forEach(([sc, mk0, uk, en], i) => {
    const mk = pre(sc, mk0), u = mk + ' ' + uk, e = mk + ' ' + en;
    if (i < o.length) out.push({ who, list, op: 'set', old: o[i], uk: u, en: e });
    else out.push({ who, list, op: 'add', uk: u, en: e });
  });
  for (let i = N[key].length; i < o.length; i++) out.push({ who, list, op: 'del', old: o[i] });
}
fs.writeFileSync(path.join(dir, 'edits_D.json'), JSON.stringify(out, null, 1));
// ---------- checks ----------
const tiers = mk => { const m = /^~(\d+) /.exec(mk); return m ? m[1].split('').map(Number) : [1, 2, 3]; };
const thr = mk => mk.replace(/^~\d+ /, '').slice(1);
const rows = key => N[key].map(([sc, mk0, uk, en]) => ({ sc, mk: pre(sc, mk0), uk, en }));
const steps = {
 fed_hugin: ['M:м_ревнощі', 'H:х_ситий', 'M:м_погроза'], fed_munin: ['H:х_голодний', 'M:м_ситий', 'H:х_кінець'],
 gap_h: ['H:х_хвалиться', 'M:м_відбивається', 'H:х_кінець'], gap_m: ['M:м_хвалиться', 'H:х_відбивається', 'M:м_кінець'],
 dungeon: ['H:х_данж', 'M:м_данж', 'H:х_данж_кінець'], fall: ['M:м_падіння', 'H:х_падіння', 'M:м_падіння_кінець'],
 heavy: ['M:м_вага', 'H:х_вага', 'M:м_вага_кінець'], portal: ['M:м_портал', 'H:х_портал', 'M:м_портал_кінець'] };
let bad = 0;
for (const sc in steps) {
  const [a, b, c] = steps[sc].map(k => rows(k).filter(r => r.sc === sc));
  const opens = new Set(a.map(x => thr(x.mk)));
  for (const t of opens) for (const tr of [1, 2, 3]) { const n = b.filter(x => thr(x.mk).split('>')[0].split('|').includes(t) && tiers(x.mk).includes(tr)).length; if (n < 2) { bad++; console.log('reply short', sc, t, tr, n); } }
  const nexts = new Set(b.map(x => thr(x.mk).split('>')[1]));
  for (const x of b) if (!thr(x.mk).includes('>')) { bad++; console.log('no chain', x.mk); }
  for (const t of nexts) for (const tr of [1, 2, 3]) { const n = c.filter(x => thr(x.mk) === t && tiers(x.mk).includes(tr)).length; if (n < 2) { bad++; console.log('close short', sc, t, tr, n); } }
  for (const x of c) if (!nexts.has(thr(x.mk))) { bad++; console.log('orphan close', sc, x.mk); }
  for (const x of b) for (const p of thr(x.mk).split('>')[0].split('|')) if (!opens.has(p)) { bad++; console.log('orphan reply', sc, x.mk); }
  for (const x of a.concat(b, c)) for (const t of thr(x.mk).split(/[>|]/)) if (!t.startsWith(sc + '.')) { bad++; console.log('prefix', sc, x.mk); }
}
// every line of my lists belongs to some scene check
for (const k in N) for (const r of rows(k)) if (!/^(~\d+ )?\^\S+$/.test(r.mk)) { bad++; console.log('mark', r.mk); }
// swears: lists that get a {м_вигук}/{м_лайка} added keep at most 1, others at most 2; same root twice
const sw = /(\{м_слівце\}|бля|курв|сук[аи]|нахуй|хуй|хуя|хуї|пизд|їба|срак|сраці|гівн|падл|херов)/gi;
const tight = ['M:м_ревнощі', 'M:м_ситий', 'M:м_відбивається', 'M:м_хвалиться', 'M:м_кінець', 'M:м_данж', 'M:м_падіння', 'M:м_вага', 'M:м_портал'];
for (const k in N) if (k.startsWith('M:')) for (const r of rows(k)) { const m = (r.uk.match(sw) || []).map(x => x.toLowerCase()); const lim = tight.includes(k) ? 1 : 2; if (m.length > lim) { console.log('swears', k, m.length, r.uk); bad++; } if (new Set(m).size < m.length) { console.log('root twice', r.uk); bad++; } }
// gender split sanity
for (const k in N) for (const r of rows(k)) { if (/\{\|/.test(r.uk) && !/сам\{\|а\}/.test(r.uk)) console.log('check form', r.uk); }
// Hugin swears
for (const k in N) if (k.startsWith('H:')) for (const r of rows(k)) if (/(бля|хуй|сук|пизд|курв|срак)/i.test(r.uk)) { console.log('hugin swear', r.uk); bad++; }
console.log('ops', out.length, 'set', out.filter(x => x.op === 'set').length, 'add', out.filter(x => x.op === 'add').length, 'del', out.filter(x => x.op === 'del').length, 'bad', bad);
